cardCss:
.pt-card {
    background: var(--card-bg, #ffffff);
    border-radius: 14px;
    padding: 14px 18px;
    border: 1px solid var(--line, #e6e6e6);
    border-left: 4px solid var(--primary, #0f766e);
    margin-bottom: 14px;
}
.pt-head { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.pt-index { color: var(--ink-3, #64748b); font-size: 12px; font-weight: 600; }
.pt-word { font-size: calc(22px * var(--card-font-scale, 1)); font-weight: 800; color: var(--primary, #0f766e); flex: 1; }
.pt-actions { display: flex; gap: 8px; }
.pt-actions .action-btn {
    width: 40px; height: 40px; border: none; border-radius: 90px;
    background: var(--action-btn-bg, #f1f5f9); color: var(--ink-3, #64748b);
    cursor: pointer; display: flex; align-items: center; justify-content: center;
}
.pt-actions .action-btn:hover { background: var(--primary, #0f766e); color: #fff; }
.pt-actions .pt-mark.is-active { background: var(--unknown, #f43f5e); color: #fff; }
.pt-meaning { font-size: calc(15px * var(--card-font-scale, 1)); line-height: 1.7; margin-bottom: 6px; }
.pt-example { font-size: calc(13px * var(--card-font-scale, 1)); color: var(--ink-2, #475569); font-style: italic; }

cardJs:
(function () {
    'use strict';
    window.cardTemplate = {
        name: 'Pack Template Word Card',
        /* 字段声明：决定卡片可展示哪些数据字段 */
        fields: [
            { key: 'word', label: '单词', hideable: false },
            { key: 'meaning', label: '释义' },
            { key: 'example', label: '例句' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            return '<div class="pt-card" data-card-id="' + data.id + '">' +
                '<div class="pt-head">' +
                '<span class="pt-index">' + String(data.current_order).padStart(2, '0') + '</span>' +
                wrap('word', '<span class="pt-word">' + (d.word || '') + '</span>') +
                '<div class="pt-actions">' +
                '<button class="action-btn" data-action="play" data-tooltip="发音"><i class="fa-solid fa-volume-high"></i></button>' +
                '<button class="action-btn pt-mark ' + markActive + '" data-action="mark" data-tooltip="标记"><i class="fa-solid fa-bookmark"></i></button>' +
                '</div>' +
                '</div>' +
                wrap('meaning', '<div class="pt-meaning">' + (d.meaning || '') + '</div>') +
                wrap('example', '<div class="pt-example">' + (d.example || '') + '</div>') +
                '</div>';
        },
        init: function (cardElement, cardData, api) {
            var pb = cardElement.querySelector('[data-action="play"]');
            if (pb) pb.addEventListener('click', function () {
                var d = cardData.data || {};
                if (d.word) api.playAudio(d.word);
                api.track('audio_play');
            });
            var mb = cardElement.querySelector('[data-action="mark"]');
            if (mb) mb.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
        },
        update: function (cardElement, cardData, api) {
            var p = cardElement.parentElement;
            if (p) { cardElement.outerHTML = this.render('', cardData, api); }
        }
    };
})();
